import math
last=0.0
def control(obs):
 global last
 h=obs['hitch_deg']; th=math.radians(-h)
 cam=obs.get('views',{}).get('camera')
 if cam:
  sides=[[],[]]
  for b,d in cam.get('walls',[]):
   a=math.radians(b)-th
   s=-d*math.cos(a); y=d*math.sin(a)
   if s>0.3:
    sides[0 if y<0 else 1].append((s,y))
  for side in sides: side.sort()
  def interp(points,s):
   for i in range(len(points)-1):
    a,b=points[i],points[i+1]
    if a[0]<=s<=b[0] and b[0]>a[0]:
     return a[1]+(b[1]-a[1])*(s-a[0])/(b[0]-a[0])
   return None
  for distance in [4.0,3.5,3.0,2.5,2.0]:
   l=interp(sides[0],distance); r=interp(sides[1],distance)
   if l is not None and r is not None:
    y=(l+r)/2
    desired=max(-29,min(29,math.degrees(math.atan2(7.0*y,distance*distance+y*y))))
    last+=0.18*(desired-last)
    break
 equilibrium=math.degrees(math.atan2(2.75*math.sin(math.radians(h)),2.6+1.05*math.cos(math.radians(h))))
 steer=max(-34,min(34,equilibrium+1.7*(h-last)))
 return (steer,-0.7,-23)

