import math
x=0.; y=0.; th=0.; last=None
scans={}
def control(o):
 global x,y,th,last
 t=o['t']; dt=o['dt'] if last is not None else 0.; last=t
 v=o['motion']['v_mps']; w=v*math.tan(math.radians(o['steer_deg']))/2.5
 x+=v*dt*math.cos(th+w*dt/2); y+=v*dt*math.sin(th+w*dt/2); th+=w*dt
 for name in ('left_mirror','right_mirror'):
  view=o['views'].get(name)
  if view:
   pts=[]; ox,oy=view['origin']
   for b,d in view['walls']:
    b=math.radians(b); px=ox+d*math.cos(b); py=oy+d*math.sin(b)
    pts.append((x+px*math.cos(th)-py*math.sin(th),y+px*math.sin(th)+py*math.cos(th)))
   scans[name]=(t,pts)
 h=o['hitch_deg']; a=th-math.radians(h)
 rx,ry=o['rig']['trailer_rear']; rx,ry=x+rx*math.cos(th)-ry*math.sin(th),y+rx*math.sin(th)+ry*math.cos(th)
 vals=[]
 for name in ('left_mirror','right_mirror'):
  if name not in scans: continue
  age,pts=scans[name]
  if t-age>6: continue
  candidates=[]
  for px,py in pts:
   dx=px-rx; dy=py-ry
   s=-dx*math.cos(a)-dy*math.sin(a); z=-dx*math.sin(a)+dy*math.cos(a)
   if 1<s<7 and abs(z)<8: candidates.append((s,z))
  if candidates:
   sw=sum(math.exp(-((s-3.8)/1.3)**2) for s,z in candidates)
   if sw>0.05: vals.append(sum(z*math.exp(-((s-3.8)/1.3)**2) for s,z in candidates)/sw)
 steer=0.52*h
 speed=-0.65 if len(vals)==2 else -0.25
 if len(vals)==2:
  err=sum(vals)/2
  steer-=2.1*math.degrees(math.atan2(err,3.8))
 if abs(h)>38:
  speed=0.; wake('Large hitch angle; stopped for assessment')
 look=64 if int(t/1.8)%2==0 else -64
 return (max(-42,min(42,steer)),speed,look)

